<template>
  <!-- Barra superior fija con menú hamburguesa -->
  <header ref="wrap" class="nav-wrap">
    <div class="nav-wrap__inner">
      <div class="nav">
        <a href="#inicio" class="nav__brand" @click="closeMenu">
          <img class="nav__emblem" :src="emblema" alt="" width="59" height="34" />
          <span class="nav__name">Cochera Belgrano</span>
        </a>

        <div class="nav__actions">
          <a
            class="btn btn--green nav__cta"
            :href="consultaUrl"
            target="_blank"
            rel="noopener noreferrer"
          >Escribinos</a>

          <button
            type="button"
            class="nav__toggle"
            :aria-expanded="isMenuOpen ? 'true' : 'false'"
            aria-controls="menu-principal"
            :aria-label="isMenuOpen ? 'Cerrar menú' : 'Abrir menú'"
            @click="toggleMenu"
          >
            <svg v-if="isMenuOpen" width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.4" stroke-linecap="round" aria-hidden="true" focusable="false">
              <path d="M6 6l12 12M18 6L6 18" />
            </svg>
            <svg v-else width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.4" stroke-linecap="round" aria-hidden="true" focusable="false">
              <path d="M4 7h16M4 12h16M4 17h16" />
            </svg>
          </button>
        </div>
      </div>

      <transition name="menu">
        <nav v-if="isMenuOpen" id="menu-principal" class="menu" aria-label="Menú principal">
          <a href="#inicio" class="menu__link" @click="closeMenu">Inicio</a>
          <a href="#servicios" class="menu__link" @click="closeMenu">Servicios</a>
          <a href="#contacto" class="menu__link" @click="closeMenu">Contacto</a>
          <a :href="mapsUrl" class="menu__link" target="_blank" rel="noopener noreferrer" @click="closeMenu">Cómo llegar</a>
          <a :href="consultaUrl" class="btn btn--white menu__cta" target="_blank" rel="noopener noreferrer" @click="closeMenu">
            Escribinos por WhatsApp
          </a>
        </nav>
      </transition>
    </div>
  </header>
  <div class="nav-spacer" aria-hidden="true"></div>

  <!-- Portada -->
  <section id="inicio" class="hero">
    <span class="hero__stripe hero__stripe--a" aria-hidden="true"></span>
    <span class="hero__stripe hero__stripe--b" aria-hidden="true"></span>

    <div class="container hero__inner">
      <div class="hero__text">
        <p class="badge">
          <span class="badge__dot" aria-hidden="true"></span>
          Abierto las 24 hs
        </p>

        <h1 class="hero__title">
          Estacioná tranquilo. <span class="hero__accent">A cualquier hora.</span>
        </h1>

        <p class="hero__lead">Cochera segura en el centro de Mar del Plata, con vigilancia y valet parking.</p>

        <div class="hero__actions">
          <a class="btn btn--green" :href="consultaUrl" target="_blank" rel="noopener noreferrer">WhatsApp</a>
          <a class="btn btn--outline" :href="mapsUrl" target="_blank" rel="noopener noreferrer">
            <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false">
