              <circle cx="12" cy="10" r="2.5" />
            </svg>
            {{ direccionCorta }}
          </a>
        </div>
      </div>

      <div class="hero__logo">
        <div class="logo-card">
          <img class="logo-card__img" :src="logo" alt="Logo de Cochera Belgrano" width="757" height="744" />
        </div>
      </div>
    </div>
  </section>
</template>

<script>
import { NEGOCIO, whatsappUrl } from '../config';
import emblema from '../assets/emblema-verde.png';
import logo from '../assets/logo-verde.png';

export default {
  name: 'AppHeader',
  data() {
    return {
      isMenuOpen: false,
      emblema,
      logo,
      direccionCorta: NEGOCIO.direccionCorta,
      mapsUrl: NEGOCIO.mapsUrl,
    };
  },
  computed: {
    consultaUrl() {
      return whatsappUrl();
    },
  },
  methods: {
    toggleMenu() {
      this.isMenuOpen = !this.isMenuOpen;
    },
    closeMenu() {
      this.isMenuOpen = false;
    },
    onKeydown(event) {
      if (event.key === 'Escape') this.closeMenu();
    },
    onDocumentClick(event) {
      // Cierra el menú al tocar fuera de la barra.
      // Se usa composedPath() porque Vue puede reemplazar el ícono del botón antes de que
      // este evento llegue acá, y entonces event.target ya no estaría dentro de la barra.
      const wrap = this.$refs.wrap;
      if (!this.isMenuOpen || !wrap) return;
      const path = event.composedPath ? event.composedPath() : [];
      if (!path.includes(wrap)) this.closeMenu();
    },
  },
  mounted() {
    window.addEventListener('keydown', this.onKeydown);
    document.addEventListener('click', this.onDocumentClick);
  },
  beforeUnmount() {
    window.removeEventListener('keydown', this.onKeydown);
    document.removeEventListener('click', this.onDocumentClick);
  },
};
</script>

